package agentcli

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	agentConfig "github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelregistry"
	"github.com/easel/fizeau/internal/runtimesignals"
)

type modelsCommandOptions struct {
	JSON         bool
	Provider     string
	PowerMin     int
	PowerMax     int
	IncludeNoise bool
	Refresh      modelsRefreshMode
	Ref          string
}

type modelsRefreshMode int

const (
	modelsRefreshNone modelsRefreshMode = iota
	modelsRefreshRouting
	modelsRefreshAll
)

type modelsSnapshotFreshness struct {
	State         string
	Hint          string
	RoutingStale  bool
	AnyStale      bool
	RefreshFailed bool
}

type modelDetail struct {
	CanonicalID       string                   `json:"canonical_id"`
	KnownModel        modelregistry.KnownModel `json:"known_model"`
	RawDiscoveryData  json.RawMessage          `json:"raw_discovery_data,omitempty"`
	CatalogEntry      *modelcatalog.ModelEntry `json:"catalog_entry,omitempty"`
	RuntimeSignal     *runtimesignals.Signal   `json:"runtime_signal,omitempty"`
	AutoRoutable      autoRoutableComposition  `json:"auto_routable"`
	SourceMeta        modelregistry.SourceMeta `json:"source_meta"`
	SnapshotGenerated time.Time                `json:"snapshot_generated_at"`
	FreshnessState    string                   `json:"freshness_state,omitempty"`
	FreshnessHint     string                   `json:"freshness_hint,omitempty"`
}

type autoRoutableComposition struct {
	AutoRoutable bool   `json:"auto_routable"`
	BlockedBy    string `json:"blocked_by,omitempty"`
	Provider     bool   `json:"provider"`
	Catalog      bool   `json:"catalog"`
	Status       bool   `json:"status"`
}

func cmdModels(workDir string, args []string) int {
	opts, err := parseModelsArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	var (
		snapshot modelregistry.ModelSnapshot
		cfg      *agentConfig.Config
		cat      *modelcatalog.Catalog
		cache    *discoverycache.Cache
	)
	switch opts.Refresh {
	case modelsRefreshRouting:
		snapshot, cfg, cat, cache, err = modelsRefreshExecutor(context.Background(), workDir, modelregistry.RefreshRouting)
	case modelsRefreshAll:
		snapshot, cfg, cat, cache, err = modelsRefreshExecutor(context.Background(), workDir, modelregistry.RefreshAll)
	default:
		snapshot, cfg, cat, cache, err = loadModelSnapshot(workDir, modelregistry.RefreshNone)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	freshness := summarizeModelsFreshness(snapshot)
	if opts.Refresh == modelsRefreshNone && freshness.RoutingStale && modelsBestEffortRefreshRequester != nil {
		modelsBestEffortRefreshRequester(context.Background(), modelregistry.RefreshRouting)
	}

	if opts.Ref != "" {
		return cmdModelsDetail(snapshot, cfg, cat, cache, opts, freshness)
	}
	return cmdModelsList(snapshot, opts, freshness)
}

func parseModelsArgs(args []string) (modelsCommandOptions, error) {
	opts := modelsCommandOptions{Refresh: modelsRefreshNone}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--json":
			opts.JSON = true
		case arg == "--refresh":
			if opts.Refresh == modelsRefreshAll {
				return opts, fmt.Errorf("--refresh and --refresh-all cannot be combined")
			}
			opts.Refresh = modelsRefreshRouting
		case arg == "--refresh-all":
			if opts.Refresh == modelsRefreshRouting {
				return opts, fmt.Errorf("--refresh and --refresh-all cannot be combined")
			}
			opts.Refresh = modelsRefreshAll
		case arg == "--no-refresh":
			if opts.Refresh != modelsRefreshNone {
				return opts, fmt.Errorf("--refresh and --no-refresh cannot be combined")
			}
		case arg == "--include-noise":
			opts.IncludeNoise = true
		case arg == "--provider":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--provider requires a value")
			}
			opts.Provider = args[i]
		case strings.HasPrefix(arg, "--provider="):
			opts.Provider = strings.TrimPrefix(arg, "--provider=")
		case arg == "--power-min":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-min requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case strings.HasPrefix(arg, "--power-min="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-min="))
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case arg == "--power-max":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-max requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "--power-max="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-max="))
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "-"):
			return opts, fmt.Errorf("unknown models flag %s", arg)
		default:
			if opts.Ref != "" {
				return opts, fmt.Errorf("models accepts at most one ref")
			}
			opts.Ref = arg
		}
	}
	return opts, nil
}

func loadModelSnapshot(workDir string, refresh modelregistry.RefreshMode) (modelregistry.ModelSnapshot, *agentConfig.Config, *modelcatalog.Catalog, *discoverycache.Cache, error) {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cat, err := cfg.LoadModelCatalog()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	root, err := modelCacheRoot()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cache := &discoverycache.Cache{Root: root}
	snapshot, err := modelregistry.AssembleWithOptions(context.Background(), cfg, cat, cache, modelregistry.AssembleOptions{Refresh: refresh})
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	return snapshot, cfg, cat, cache, nil
}

var modelsRefreshExecutor = func(ctx context.Context, workDir string, scope modelregistry.RefreshScope) (modelregistry.ModelSnapshot, *agentConfig.Config, *modelcatalog.Catalog, *discoverycache.Cache, error) {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cat, err := cfg.LoadModelCatalog()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	root, err := modelCacheRoot()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cache := &discoverycache.Cache{Root: root}
	snapshot, err := modelregistry.RefreshModels(ctx, cfg, cat, cache, scope)
	if err != nil {
		return modelregistry.ModelSnapshot{}, cfg, cat, cache, err
	}
	return snapshot, cfg, cat, cache, nil
}

var modelsBestEffortRefreshRequester func(context.Context, modelregistry.RefreshScope)

func modelCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func cmdModelsList(snapshot modelregistry.ModelSnapshot, opts modelsCommandOptions, freshness modelsSnapshotFreshness) int {
	models := filterModelRows(snapshot.Models, opts)
	if opts.JSON {
		out := struct {
			modelregistry.ModelSnapshot
			FreshnessState string `json:"freshness_state,omitempty"`
			FreshnessHint  string `json:"freshness_hint,omitempty"`
		}{
			ModelSnapshot:  snapshot,
			FreshnessState: freshness.State,
			FreshnessHint:  freshness.Hint,
		}
		out.Models = models
		data, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	printModelsFreshness(freshness)
	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "PROVIDER\tMODEL\tFAMILY\tVERSION\tTIER\tPOWER\tCOST/M\tSTATUS\tCATALOG QUOTA\tRUNTIME QUOTA\tAUTO")

package fizeau

import (
	"context"
	"os"
	"path/filepath"
	"strings"

	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelsnapshot"
)

func assembleModelSnapshotFromServiceConfig(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string) (modelsnapshot.ModelSnapshot, error) {
	return assembleModelSnapshotFromServiceConfigWithOptions(ctx, sc, cat, cacheRoot, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshBackground})
}

func assembleModelSnapshotFromServiceConfigWithOptions(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string, opts modelsnapshot.AssembleOptions) (modelsnapshot.ModelSnapshot, error) {
	var cfg *modelsnapshot.Config
	if sc != nil {
		cfg = serviceConfigToModelSnapshotConfig(sc)
	}
	cache := &discoverycache.Cache{Root: cacheRoot}
	return modelsnapshot.AssembleWithOptions(ctx, cfg, cat, cache, opts)
}

func serviceSnapshotCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func serviceConfigToModelSnapshotConfig(sc ServiceConfig) *modelsnapshot.Config {
	if sc == nil {
		return nil
	}
	cfg := &modelsnapshot.Config{
		Default:   sc.DefaultProviderName(),
		Providers: make(map[string]modelsnapshot.ProviderConfig, len(sc.ProviderNames())),
	}
	for _, name := range sc.ProviderNames() {
		entry, ok := sc.Provider(name)
		if !ok {
			continue
		}
		cfg.Providers[name] = modelSnapshotProviderConfig(entry)
	}
	return cfg
}

func modelSnapshotProviderConfig(entry ServiceProviderEntry) modelsnapshot.ProviderConfig {
	out := modelsnapshot.ProviderConfig{
		Type:             entry.Type,
		BaseURL:          entry.BaseURL,
		ServerInstance:   entry.ServerInstance,
		Endpoints:        make([]modelsnapshot.ProviderEndpoint, 0, len(entry.Endpoints)),
		APIKey:           entry.APIKey,
		Headers:          cloneStringMap(entry.Headers),
		Model:            entry.Model,
		Billing:          string(entry.Billing),
		IncludeByDefault: nil,
		ContextWindow:    entry.ContextWindow,
		ConfigError:      entry.ConfigError,
		DailyTokenBudget: entry.DailyTokenBudget,
	}
	if entry.IncludeByDefaultSet {
		v := entry.IncludeByDefault
		out.IncludeByDefault = &v
		out.IncludeByDefaultSet = true
	}
	for _, endpoint := range entry.Endpoints {
		out.Endpoints = append(out.Endpoints, modelsnapshot.ProviderEndpoint{
			Name:           endpoint.Name,
			BaseURL:        endpoint.BaseURL,
			ServerInstance: endpoint.ServerInstance,
		})
	}
	return out
}

func cloneStringMap(src map[string]string) map[string]string {
	if len(src) == 0 {
		return nil
	}
	out := make(map[string]string, len(src))
	for k, v := range src {
		out[k] = v
	}
	return out
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/compaction"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modeleligibility"
	"github.com/easel/fizeau/internal/modelsnapshot"
	"github.com/easel/fizeau/internal/provider/utilization"
	"github.com/easel/fizeau/internal/routing"
	"github.com/easel/fizeau/internal/serverinstance"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// fiz-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	if req.Harness != "" && req.Model != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
			return nil, err
		}
	}
	if req.Harness != "" && req.Policy != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessPolicy(canonical, cfg, req.Policy); err != nil {
			return nil, err
		}
	}
	cat := serviceRoutingCatalog()
	requestedPolicy := req.Policy
	policy := routingPolicyForName(cat, requestedPolicy)
	powerPolicy := routePowerPolicyForRequest(cat, req)
	providerPreference, err := providerPreferenceForPolicy(cat, requestedPolicy)
	if err != nil {
		return &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
		}, err
	}
	in, snapshot := s.buildRoutingInputsWithCatalog(ctx, cat, modelsnapshot.RefreshNone)

	resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
	if modelErr != nil {
		result := &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
			Candidates:      modelCandidates,
		}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(modelErr, result.Candidates, req.Policy)
	}

	rReq := routing.Request{
		Policy:                policy,
		Model:                 resolvedModel,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		CorrelationID:         req.CorrelationID,
		AllowLocal:            req.AllowLocal,
		Require:               append([]string(nil), req.Require...),
	}
	if policyEntry, _, ok := policyForName(cat, requestedPolicy); ok {
		rReq.AllowLocal = rReq.AllowLocal || policyEntry.AllowLocal
		rReq.Require = append(append([]string(nil), policyEntry.Require...), rReq.Require...)
	}
	rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalatePolicyLadder(rReq, in, err, req.Policy); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec, powerPolicy)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		result.RequestedPolicy = req.Policy
		result.PowerPolicy = powerPolicy
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(err, result.Candidates, req.Policy)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	if result != nil && result.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(result.Provider)
		result.Endpoint = endpoint
	}
	s.annotateRouteDecisionSnapshotEvidence(result, snapshot)
	s.annotateRouteDecisionEvidence(result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.RequestedPolicy = req.Policy
		result.PowerPolicy = powerPolicy
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision, powerPolicy RoutePowerPolicy) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:        dec.Harness,
		Provider:       dec.Provider,
		Endpoint:       dec.Endpoint,
		ServerInstance: dec.ServerInstance,
		Model:          dec.Model,
		Reason:         dec.Reason,
		Candidates:     routeCandidatesFromInternal(dec.Candidates, powerPolicy),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate, powerPolicy RoutePowerPolicy) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate, powerPolicy)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate, powerPolicy RoutePowerPolicy) RouteCandidate {
	components := RouteCandidateComponents{
		Power:            candidate.Power,
		Cost:             candidate.CostUSDPer1kTokens,
		CostClass:        candidate.CostClass,
		LatencyMS:        candidate.LatencyMS,
		SpeedTPS:         candidate.SpeedTPS,
		Utilization:      candidate.Utilization,
		SuccessRate:      candidate.SuccessRate,
		QuotaOK:          candidate.QuotaOK,
		QuotaPercentUsed: candidate.QuotaPercentUsed,
		QuotaTrend:       candidate.QuotaTrend,
		Capability:       capabilityScoreForCostClass(candidate.CostClass),
		ContextHeadroom:  candidate.ContextHeadroom,
		StickyAffinity:   candidate.StickyAffinity,
	}
	powerHintFit := scorePowerHintFit(candidate.Power, powerPolicy)
	scorePower := candidate.ScoreComponents["power"]
	scoreCost := candidate.ScoreComponents["cost"]
	scorePerformance := candidate.ScoreComponents["performance"]
	scoreLocality := candidate.ScoreComponents["deployment_locality"]
	scoreQuota := candidate.ScoreComponents["quota_health"]
	scoreUtilization := candidate.ScoreComponents["utilization"]
	components.PowerHintFit = powerHintFit
	components.PowerWeightedCapability = scorePower - powerHintFit + positiveScorePart(scoreCost)
	components.LatencyWeight = positiveScorePart(scorePerformance)
	components.StaleSignalPenalty = positiveScorePart(-scorePerformance)
	components.PlacementBonus = scoreLocality + candidate.StickyAffinity
	components.QuotaBonus = positiveScorePart(scoreQuota)
	components.MarginalCostPenalty = positiveScorePart(-scoreCost)
	components.AvailabilityPenalty = positiveScorePart(-scoreQuota) + positiveScorePart(-scoreUtilization)
	return RouteCandidate{
		Harness:             candidate.Harness,
		Provider:            candidate.Provider,
		Billing:             candidate.Billing,
		ActualCashSpend:     candidate.ActualCashSpend,
		Endpoint:            candidate.Endpoint,
		ServerInstance:      candidate.ServerInstance,
		Model:               candidate.Model,
		Score:               candidate.Score,
		CostUSDPer1kTokens:  candidate.CostUSDPer1kTokens,
		CostSource:          candidate.CostSource,
		EffectiveCost:       candidate.CostUSDPer1kTokens,
		EffectiveCostSource: candidate.CostSource,
		Eligible:            candidate.Eligible,
		Reason:              candidate.Reason,
		FilterReason:        publicFilterReason(candidate),
		ContextLength:       candidate.ContextLength,
		ContextSource:       candidate.ContextSource,
		Components:          components,
	}
}

func scorePowerHintFit(power int, policy RoutePowerPolicy) float64 {
	if power <= 0 {
		return 0
	}
	if policy.MinPower > 0 && power < policy.MinPower {
		// Mirror the engine scorer: materially underpowered routes should not
		// win just because they are cheap.
		return -float64(policy.MinPower-power) * 12
	}
	if policy.MaxPower > 0 && power > policy.MaxPower {
		return -float64(power - policy.MaxPower)
	}
	return 0
}

func positiveScorePart(v float64) float64 {
	if v > 0 {
		return v
	}
	return 0
}

type routeSnapshotCandidateKey struct {
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
}

func routeSnapshotCandidateIndex(snapshot modelsnapshot.ModelSnapshot) map[routeSnapshotCandidateKey]modelsnapshot.KnownModel {
	if len(snapshot.Models) == 0 {
		return nil
	}
	out := make(map[routeSnapshotCandidateKey]modelsnapshot.KnownModel, len(snapshot.Models))
	for _, row := range snapshot.Models {
		key := routeSnapshotCandidateKey{
			Provider:       strings.TrimSpace(row.Provider),
			Endpoint:       strings.TrimSpace(row.EndpointName),
			ServerInstance: strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance)),
			Model:          strings.TrimSpace(row.ID),
		}
		if key.Provider == "" || key.Model == "" {
			continue
		}

package agentcli

// route_status.go implements `fiz route-status --overrides`
// (ADR-006 §5). The base `route-status` command lives in routing_smart.go
// and dispatches into this file when --overrides is set.
//
// This is the operator-facing surface that prints override_class_breakdown
// over a recent time window so operators can diagnose where auto-routing
// is mis-deciding. Per ADR-006 §Migration, this is an operator-driven
// feedback loop; automatic learning from this signal is a future ADR.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"text/tabwriter"
	"time"

	rootfizeau "github.com/easel/fizeau"
	agentConfig "github.com/easel/fizeau/internal/config"
)

const defaultRouteStatusOverridesWindow = 7 * 24 * time.Hour

// routeStatusOverridesOutput is the stable JSON envelope emitted by
// `route-status --overrides --json`. The shape is snapshot-tested in
// TestRouteStatusOverridesJSONStable; new fields must be added at the end
// or behind a new flag.
type routeStatusOverridesOutput struct {
	Since                    string                           `json:"since"`
	WindowStart              time.Time                        `json:"window_start"`
	WindowEnd                time.Time                        `json:"window_end"`
	AxisFilter               string                           `json:"axis_filter,omitempty"`
	AutoAcceptanceRate       float64                          `json:"auto_acceptance_rate"`
	OverrideDisagreementRate float64                          `json:"override_disagreement_rate"`
	TotalRequests            int                              `json:"total_requests"`
	TotalOverrides           int                              `json:"total_overrides"`
	OverrideClassBreakdown   []rootfizeau.OverrideClassBucket `json:"override_class_breakdown"`
}

// cmdRouteStatusOverrides implements the --overrides mode. It is wired in
// from cmdRouteStatus (routing_smart.go); kept here to keep the operator
// surface self-contained.
func cmdRouteStatusOverrides(workDir, since, axis string, jsonOut bool) int {
	return runRouteStatusOverrides(workDir, since, axis, jsonOut, os.Stdout, os.Stderr, time.Now().UTC())
}

func runRouteStatusOverrides(workDir, since, axis string, jsonOut bool, stdout, stderr io.Writer, now time.Time) int {
	if err := validateRouteStatusOverridesAxis(axis); err != nil {
		fmt.Fprintf(stderr, "error: %s\n", err)
		return 2
	}

	dur, err := parseRouteStatusOverridesSince(since)
	if err != nil {
		fmt.Fprintf(stderr, "error: %s\n", err)
		return 2
	}
	start := now.Add(-dur)
	end := now

	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(stderr, "error: %s\n", err)
		return 1
	}
	svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
		ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
		SessionLogDir: sessionLogDir(workDir, cfg),
	})
	if err != nil {
		fmt.Fprintf(stderr, "error: %s\n", err)
		return 1
	}

	report, err := svc.UsageReport(context.Background(), rootfizeau.UsageReportOptions{
		Since: formatUsageWindowSince(start, end),
		Now:   now,
	})
	if err != nil {
		fmt.Fprintf(stderr, "error: %s\n", err)
		return 1
	}

	metrics := report.RoutingQuality
	filtered := filterOverrideBreakdownByAxis(metrics.OverrideClassBreakdown, axis)

	out := routeStatusOverridesOutput{
		Since:                    since,
		WindowStart:              start,
		WindowEnd:                end,
		AxisFilter:               axis,
		AutoAcceptanceRate:       metrics.AutoAcceptanceRate,
		OverrideDisagreementRate: metrics.OverrideDisagreementRate,
		TotalRequests:            metrics.TotalRequests,
		TotalOverrides:           metrics.TotalOverrides,
		OverrideClassBreakdown:   filtered,
	}
	if out.OverrideClassBreakdown == nil {
		out.OverrideClassBreakdown = []rootfizeau.OverrideClassBucket{}
	}

	if jsonOut {
		writeRouteStatusOverridesJSON(stdout, out)
		return 0
	}
	writeRouteStatusOverridesText(stdout, out)
	return 0
}

// parseRouteStatusOverridesSince parses --since as a Go duration. Empty
// means the default 7d window.
func parseRouteStatusOverridesSince(spec string) (time.Duration, error) {
	if spec == "" {
		return defaultRouteStatusOverridesWindow, nil
	}
	d, err := time.ParseDuration(spec)
	if err != nil {
		return 0, fmt.Errorf("--since: %w", err)
	}
	if d <= 0 {
		return 0, fmt.Errorf("--since: must be positive, got %s", spec)
	}
	return d, nil
}

// validateRouteStatusOverridesAxis rejects unknown axis values. Empty is
// allowed (no filter).
func validateRouteStatusOverridesAxis(axis string) error {
	switch axis {
	case "", "harness", "provider", "model":
		return nil
	default:
		return fmt.Errorf("--axis: must be one of harness|provider|model, got %q", axis)
	}
}

// filterOverrideBreakdownByAxis returns rows where Axis == axis. Empty axis
// returns the input unchanged. Rows are returned in the same deterministic
// order produced by the aggregator.
func filterOverrideBreakdownByAxis(rows []rootfizeau.OverrideClassBucket, axis string) []rootfizeau.OverrideClassBucket {
	if axis == "" {
		return rows
	}
	out := make([]rootfizeau.OverrideClassBucket, 0, len(rows))
	for _, r := range rows {
		if r.Axis == axis {
			out = append(out, r)
		}
	}
	return out
}

// sortOverrideBreakdownForDisplay returns a copy sorted by Count desc, then
// success rate desc, then deterministic key. The default JSON ordering is
// preserved by the aggregator; this is the table-render ordering.
func sortOverrideBreakdownForDisplay(rows []rootfizeau.OverrideClassBucket) []rootfizeau.OverrideClassBucket {
	out := make([]rootfizeau.OverrideClassBucket, len(rows))
	copy(out, rows)
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		li := bucketSuccessRate(out[i])
		lj := bucketSuccessRate(out[j])
		if li != lj {
			return li > lj
		}
		if out[i].PromptFeatureBucket != out[j].PromptFeatureBucket {
			return out[i].PromptFeatureBucket < out[j].PromptFeatureBucket
		}
		if out[i].Axis != out[j].Axis {
			return out[i].Axis < out[j].Axis
		}
		return !out[i].Match && out[j].Match
	})
	return out
}

func bucketSuccessRate(b rootfizeau.OverrideClassBucket) float64 {
	total := b.SuccessOutcomes + b.StalledOutcomes + b.FailedOutcomes + b.CancelledOutcomes + b.UnknownOutcomes
	if total == 0 {
		return 0
	}
	return float64(b.SuccessOutcomes) / float64(total)
}

func writeRouteStatusOverridesJSON(w io.Writer, out routeStatusOverridesOutput) {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	_ = enc.Encode(out)
}

func writeRouteStatusOverridesText(w io.Writer, out routeStatusOverridesOutput) {
	fmt.Fprintf(w, "Window: %s .. %s (%s)\n",
		out.WindowStart.Format(time.RFC3339),
		out.WindowEnd.Format(time.RFC3339),
		windowDurationLabel(out.Since))
	if out.AxisFilter != "" {
		fmt.Fprintf(w, "Axis filter: %s\n", out.AxisFilter)
	}
	fmt.Fprintf(w, "Auto-acceptance rate: %.3f (%d / %d)\n",
		out.AutoAcceptanceRate,
		out.TotalRequests-out.TotalOverrides,
		out.TotalRequests)
	fmt.Fprintf(w, "Override disagreement rate: %.3f (%d overrides)\n",
		out.OverrideDisagreementRate,
		out.TotalOverrides)

	if len(out.OverrideClassBreakdown) == 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "No override events recorded in this window.")
		return
	}

	fmt.Fprintln(w)
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "PROMPT_FEATURES\tAXIS\tMATCH\tCOUNT\tSUCCESS%\tSUCCESS\tSTALLED\tFAILED\tCANCELLED\tUNKNOWN")
	for _, b := range sortOverrideBreakdownForDisplay(out.OverrideClassBreakdown) {
		successPct := bucketSuccessRate(b) * 100
		fmt.Fprintf(tw, "%s\t%s\t%t\t%d\t%.1f%%\t%d\t%d\t%d\t%d\t%d\n",
			b.PromptFeatureBucket, b.Axis, b.Match, b.Count, successPct,
			b.SuccessOutcomes, b.StalledOutcomes, b.FailedOutcomes,
			b.CancelledOutcomes, b.UnknownOutcomes)
	}
	_ = tw.Flush()
}

func windowDurationLabel(since string) string {
	if since == "" {
		return "default 7d"
	}
	return since
}

// formatUsageWindowSince builds the date-range form
// "RFC3339..RFC3339" that internal/session.ParseUsageWindow accepts. We
// route through it (rather than a duration form) because the public
// UsageReport API only takes a string.
func formatUsageWindowSince(start, end time.Time) string {
	return start.UTC().Format(time.RFC3339) + ".." + end.UTC().Format(time.RFC3339)
}

