	}))
	t.Cleanup(srv.Close)

	sc := buildSnapshotAutoroutingServiceConfig(t, fixture, srv.URL+"/v1")
	seedSnapshotAutoroutingCache(t, cacheRoot, fixture, srv.URL+"/v1")

	svc := newTestService(t, ServiceOptions{ServiceConfig: sc})
	decisions := map[string]*RouteDecision{}

	t.Run("cheap", func(t *testing.T) {
		dec, err := svc.ResolveRoute(context.Background(), RouteRequest{Policy: "cheap"})
		if err != nil {
			t.Fatalf("ResolveRoute: %v", err)
		}
		if dec.Harness != "fiz" || dec.Provider != "local" || dec.Model != "gpt-5.4-nano" {
			t.Fatalf("winner=%s/%s/%s, want fiz/local/gpt-5.4-nano", dec.Harness, dec.Provider, dec.Model)
		}
		decisions["cheap"] = dec
	})

	t.Run("default", func(t *testing.T) {
		dec, err := svc.ResolveRoute(context.Background(), RouteRequest{Policy: "default"})
		if err != nil {
			t.Fatalf("ResolveRoute: %v", err)
		}
		if dec.Harness != "fiz" || dec.Provider != "local" || dec.Model != "gpt-5.4-mini" {
			t.Fatalf("winner=%s/%s/%s, want fiz/local/gpt-5.4-mini", dec.Harness, dec.Provider, dec.Model)
		}
		decisions["default"] = dec
	})

	t.Run("smart", func(t *testing.T) {
		dec, err := svc.ResolveRoute(context.Background(), RouteRequest{Policy: "smart"})
		if err != nil {
			t.Fatalf("ResolveRoute: %v", err)
		}
		if dec.Harness != "remote-optin" || dec.Provider != "remote-optin" || dec.Model != "gpt-5.5" {
			t.Fatalf("winner=%s/%s/%s, want remote-optin/remote-optin/gpt-5.5", dec.Harness, dec.Provider, dec.Model)
		}
		var sawOptOut, sawUnknown, sawDown bool
		for _, c := range dec.Candidates {
			switch {
			case c.Provider == "remote-open" && c.Model == "gpt-5.5":
				sawOptOut = true
				if c.Eligible {
					t.Fatalf("remote-open candidate should be rejected without metered opt-in: %#v", c)
				}
				if c.FilterReason != FilterReasonMeteredOptInRequired {
					t.Fatalf("remote-open FilterReason=%q, want %q", c.FilterReason, FilterReasonMeteredOptInRequired)
				}
			case c.Provider == "local-stale" && c.Model == "stale-mini":
				sawUnknown = true
				if c.Eligible {
					t.Fatalf("stale-mini should be rejected while health is unknown: %#v", c)
				}
				if c.SourceStatus != "unknown" {
					t.Fatalf("stale-mini SourceStatus=%q, want unknown", c.SourceStatus)
				}
				if c.FilterReason != "not_auto_routable" {
					t.Fatalf("stale-mini FilterReason=%q, want not_auto_routable", c.FilterReason)
				}
			case c.Provider == "remote-down" && c.Model == "gpt-5.5":
				sawDown = true
				if c.SourceStatus != "unreachable" {
					t.Fatalf("remote-down SourceStatus=%q, want unreachable", c.SourceStatus)
				}
				if c.FilterReason != "not_auto_routable" {
					t.Fatalf("remote-down FilterReason=%q, want not_auto_routable", c.FilterReason)
				}
			}
		}
		if !sawOptOut || !sawUnknown || !sawDown {
			t.Fatalf("missing expected candidates: optOut=%t unknown=%t down=%t", sawOptOut, sawUnknown, sawDown)
		}
		decisions["smart"] = dec
	})

	t.Run("exact pin", func(t *testing.T) {
		dec, err := svc.ResolveRoute(context.Background(), RouteRequest{Model: "local-exact-only"})
		if err != nil {
			t.Fatalf("ResolveRoute: %v", err)
		}
		if dec.Harness != "local-stale" || dec.Provider != "local-stale" || dec.Model != "local-exact-only" {
			t.Fatalf("winner=%s/%s/%s, want local-stale/local-stale/local-exact-only", dec.Harness, dec.Provider, dec.Model)
		}
		if len(dec.Candidates) != 1 {
			t.Fatalf("exact pin should narrow to one candidate, got %#v", dec.Candidates)
		}
		candidate := dec.Candidates[0]
		if candidate.SourceStatus != "unknown" {
			t.Fatalf("exact-pinned candidate source status=%q, want unknown", candidate.SourceStatus)
		}
		if !candidate.Eligible {
			t.Fatalf("exact-pinned candidate should remain eligible: %#v", candidate)
		}
		if candidate.ExactPinOnly != true {
			t.Fatalf("exact-pinned candidate should retain exact_pin_only evidence: %#v", candidate)
		}
		decisions["exact pin"] = dec
	})

	t.Run("exact pin failure", func(t *testing.T) {
		_, err := svc.ResolveRoute(context.Background(), RouteRequest{Model: "does-not-exist"})
		if err == nil {
			t.Fatal("ResolveRoute succeeded for an undispatchable exact pin, want a clear failure")
		}
	})

	if got := calls.Load(); got != 0 {
		t.Fatalf("unexpected provider call count = %d; snapshot replay must not probe providers", got)
	}

	_ = decisions
}

