func TestCheapPolicySelectsLowestEffectiveCostSufficientCandidate(t *testing.T) {
	in := effectiveCostRoutingInputs(true, 7, 95)

	dec, err := Resolve(Request{Policy: "cheap", MinPower: 7}, in)
	if err != nil {
